import { registerBrowserTabTools } from './src/browser-tab-mcp-sidecar.js';
const tools = new Map();
const server = { registerTool(name, config, handler) { tools.set(name, handler); } };
registerBrowserTabTools(server, { enabled: true });
const results = [];
for (const port of [17410, 17447]) {
  const inventory = await tools.get('browser.tab.list')({ port });
  const tabs = JSON.parse(inventory.content[0].text).tabs || [];
  const local = tabs.find(tab => new URL(tab.url).hostname === '127.0.0.1');
  if (!local) { results.push({ port, ok: false, reason: 'local_target_missing' }); continue; }
  const media = await tools.get('browser.tab.capture')({
    port, target_id: local.target_id, expected_url: local.url,
  });
  if (media.isError) { results.push({ port, ok: false, code: JSON.parse(media.content[0].text).code }); continue; }
  const meta = JSON.parse(media.content[1].text);
  const bytes = Buffer.from(media.content[0].data, 'base64');
  const sig = bytes.subarray(0, 8).toString('hex');
  results.push({
    port, ok: media.content[0].type === 'image' &&
      media.content[0].mimeType === 'image/png' &&
      sig === '89504e470d0a1a0a', width: meta.width, height: meta.height,
    size: bytes.length, sha256: meta.sha256, contentIsImage: media.content[0].type,
    pixelBytesInText: media.content[1].text.includes(media.content[0].data),
  });
}
console.log(JSON.stringify({ enabled: tools.size === 2, results }));
